<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../src/Services/reportes.php';
require_once __DIR__.'/../src/Services/pdf_reporte.php';
require_once __DIR__.'/../src/Services/auditoria.php';
require_once __DIR__.'/../src/Services/panel_administrador.php';

$resultados=[];$probar=static function(string $id,string $nombre,callable $prueba)use(&$resultados):void{try{$detalle=$prueba();$resultados[]=[$id,$nombre,'CUMPLE',$detalle?:'Resultado correcto.'];}catch(Throwable $e){$resultados[]=[$id,$nombre,'FALLA',$e->getMessage()];}};
$asegurar=static function(bool $condicion,string $mensaje):void{if(!$condicion)throw new RuntimeException($mensaje);};
$leer=static fn(string $ruta):string=>(string)file_get_contents(dirname(__DIR__).'/'.$ruta);
$pdo=conectarBD();

$probar('CN01','Normalizar fechas y filtros inválidos',function()use($asegurar){$f=filtrosReporte(['desde'=>'fecha','hasta'=>'otra','estado'=>'inventado','medico_id'=>'x']);$asegurar(fechaClinicaValida($f['desde'])&&fechaClinicaValida($f['hasta'])&&$f['estado']===''&&$f['medico_id']===null,'Los filtros inválidos no fueron normalizados.');return 'Entradas inválidas reemplazadas por valores seguros.';});
$probar('CN02','Corregir rango de fechas invertido',function()use($asegurar){$f=filtrosReporte(['desde'=>'2026-12-31','hasta'=>'2026-01-01']);$asegurar($f['desde']==='2026-01-01'&&$f['hasta']==='2026-12-31','El rango invertido no se corrigió.');return 'El sistema ordenó las fechas automáticamente.';});
$probar('CN03','Coincidencia entre resumen y detalle',function()use($pdo,$asegurar){$f=filtrosReporte(['desde'=>'2026-01-01','hasta'=>'2026-12-31']);$r=obtenerReporteCitas($pdo,$f);$asegurar($r['total']===count($r['detalle']),'El total no coincide con las filas.');return $r['total'].' cita(s) coincidentes.';});
$probar('CN04','Filtrar por médico, especialidad y estado',function()use($pdo,$asegurar){$base=obtenerReporteCitas($pdo,filtrosReporte(['desde'=>'2026-01-01','hasta'=>'2026-12-31']));if(!$base['detalle'])return 'Sin datos: consulta válida sin resultados.';$x=$base['detalle'][0];$m=$pdo->prepare("SELECT id FROM medicos WHERE apellidos||', '||nombres=:n");$m->execute(['n'=>$x['medico']]);$e=$pdo->prepare('SELECT id FROM especialidades WHERE nombre=:n');$e->execute(['n'=>$x['especialidad']]);$r=obtenerReporteCitas($pdo,filtrosReporte(['desde'=>'2026-01-01','hasta'=>'2026-12-31','medico_id'=>$m->fetchColumn(),'especialidad_id'=>$e->fetchColumn(),'estado'=>$x['estado']]));foreach($r['detalle'] as $fila)$asegurar($fila['medico']===$x['medico']&&$fila['especialidad']===$x['especialidad']&&$fila['estado']===$x['estado'],'Apareció una fila fuera del filtro.');return count($r['detalle']).' fila(s) respetaron todos los filtros.';});
$probar('CN05','Generar PDF paginado',function()use($asegurar){$fila=['inicio'=>'2026-11-07 10:00','fin'=>'2026-11-07 10:20','codigo_cita'=>'CITA-CAJA-NEGRA','paciente'=>'Paciente Prueba','medico'=>'Médico Prueba','especialidad'=>'Medicina General','estado'=>'confirmada','modalidad'=>'presencial','estado_pago'=>null,'monto'=>null];$filas=array_fill(0,50,$fila);$res=['total'=>50,'por_estado'=>['confirmada'=>50],'pagos'=>['cobrado'=>0]];$pdf=generarReporteCitasPdf($filas,$res,'Prueba de paginación');$asegurar(str_starts_with($pdf,'%PDF-1.4')&&str_contains($pdf,'/Count 3')&&str_ends_with($pdf,'%%EOF'),'El PDF no tiene tres páginas válidas.');return '50 filas distribuidas en 3 páginas.';});
$probar('CN06','Proteger reportes y exportaciones por rol',function()use($leer,$asegurar){foreach(['public/reportes.php','public/exportar_reporte_pdf.php','public/exportar_reporte_csv.php','public/auditoria.php'] as $a){$c=$leer($a);$asegurar(str_contains($c,'[1, 2]')||str_contains($c,'[1,2]'),"$a no restringe administración/recepción.");}return 'Paciente y médico quedan fuera de las vistas administrativas.';});
$probar('CN07','Consultar auditoría con filtros',function()use($pdo,$asegurar){$f=filtrosAuditoria(['desde'=>'2026-01-01','hasta'=>'2026-12-31','accion'=>'creacion']);$eventos=obtenerEventosAuditoria($pdo,$f);foreach($eventos as $e)$asegurar($e['accion']==='creacion','La auditoría devolvió otra operación.');return count($eventos).' creación(es) encontrada(s).';});
$probar('CN08','Mostrar panel administrativo consolidado',function()use($pdo,$asegurar){$p=obtenerPanelAdministrador($pdo);foreach(['resumen','citas','actividad'] as $k)$asegurar(array_key_exists($k,$p),"Falta $k.");foreach(['pacientes','medicos','citas_hoy','por_confirmar','cobrado_hoy','pagos_pendientes'] as $k)$asegurar(array_key_exists($k,$p['resumen']),"Falta indicador $k.");return 'Indicadores, próximas citas y actividad disponibles.';});
$probar('CN09','Conservar diseño adaptable',function()use($leer,$asegurar){$css=$leer('public/assets/css/modern.css');foreach(['max-width:1100px','max-width:640px','.admin-dashboard-grid','.audit-filters','.report-detail-table'] as $marca)$asegurar(str_contains($css,$marca),"Falta regla responsive $marca.");return 'Reglas para computadora, tableta y celular presentes.';});
$probar('CN10','Ofrecer dos formatos de reporte',function()use($leer,$asegurar){$pdf=$leer('public/exportar_reporte_pdf.php');$csv=$leer('public/exportar_reporte_csv.php');$asegurar(str_contains($pdf,'application/pdf')&&str_contains($csv,'text/csv')&&str_contains($csv,'Content-Disposition: attachment'),'Falta un formato de exportación.');return 'PDF y CSV compatible con Excel disponibles.';});

$fallas=0;foreach($resultados as [$id,$nombre,$estado,$detalle]){echo "$id | $estado | $nombre | $detalle\n";if($estado==='FALLA')$fallas++;}echo "TOTAL: ".count($resultados)." | APROBADAS: ".(count($resultados)-$fallas)." | FALLAS: $fallas\n";exit($fallas?1:0);
